// Created: 2026-08-13

/**
 * Regression guard: the deferred-debt machinery must never report ITSELF.
 *
 * Observed on 2026-08-13: every session start surfaced 2 debt markers whose
 * only source was the tracker's own docstring, which spelled the example
 * marker with a literal `//` leader. DEBT_MARKER_RE accepts a bare `*` as a
 * comment leader and only whitespace between leader and token, so a JSDoc
 * line reading " *   // <token>: ..." parses as a live marker.
 *
 * The cost was not cosmetic: a permanently non-empty ledger is one an
 * operator learns to ignore, which is exactly how a real marker gets missed.
 *
 * lib/debt-markers.ts already dodged this by writing `<leader>` as a
 * placeholder. This test makes that convention enforced rather than
 * remembered.
 */

import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { DEBT_MARKER_RE } from '../../lib/debt-markers.js';

const HERE = dirname(fileURLToPath(import.meta.url));
const SRC = join(HERE, '../..');

/** The files that define, capture, or surface debt markers. */
const MACHINERY = [
  'lib/debt-markers.ts',
  'posttool/write/debt-marker-tracker.ts',
  'instructions-loaded/session-rules-audit.ts',
];

function selfMatches(relPath: string): { line: number; text: string }[] {
  let content: string;
  try {
    content = readFileSync(join(SRC, relPath), 'utf8');
  } catch {
    return []; // file moved or absent; the roster assertion below catches that
  }
  const hits: { line: number; text: string }[] = [];
  content.split('\n').forEach((text, i) => {
    if (DEBT_MARKER_RE.test(text)) hits.push({ line: i + 1, text });
  });
  return hits;
}

describe('debt-marker machinery never self-matches', () => {
  for (const rel of MACHINERY) {
    it(`${rel} contains no parseable debt marker`, () => {
      const hits = selfMatches(rel);
      // Surface the offending line, not just a count, so the fix is obvious.
      expect(
        hits.map((h) => `${rel}:${h.line}  ${h.text.trim()}`),
        'write the example marker with a <leader> placeholder, not a literal // or #',
      ).toEqual([]);
    });
  }

  it('the roster still points at real files', () => {
    // Guards the silent-pass hole in selfMatches(): if a file is renamed, the
    // catch would return [] and every assertion above would pass vacuously.
    for (const rel of MACHINERY) {
      expect(() => readFileSync(join(SRC, rel), 'utf8'), `${rel} missing`).not.toThrow();
    }
  });

  it('still detects a genuine marker (the guard is not vacuous)', () => {
    // If DEBT_MARKER_RE ever stopped matching anything, every test above would
    // pass for the wrong reason. Pin that it still fires on a real marker.
    const token = ['ork', 'debt'].join('-');
    expect(DEBT_MARKER_RE.test(`// ${token}: in-memory cache, upgrade to redis, when multi-node`)).toBe(true);
    expect(DEBT_MARKER_RE.test(` *   <leader> ${token}: placeholder form must NOT match`)).toBe(false);
  });
});
